mapper.select:
SELECT p.product_id as productId, p.product_name AS productName, p.product_image AS productImage, p.product_seriesid AS productSeriesId, ps.series_name AS productSeriesName, p.product_levelid AS productLevelId, pl.level_name AS productLevelName, p.product_badge as productBadge, p.product_detail as productDetail, p.available as available, p.created_by AS createdBy, p.created_time AS createdTime, p.updated_by AS updatedBy, p.updated_time AS updatedTime FROM market_product p LEFT JOIN market_series ps ON p.product_seriesid = ps.series_id LEFT JOIN product_level pl ON p.product_levelid = pl.level_id WHERE 1=1
AND p.product_id = #{productId}
AND p.product_name LIKE CONCAT('%', #{productName}, '%')
AND p.product_seriesid = #{productSeriesId}
AND p.product_levelid = #{productLevelId}
ORDER BY p.product_id
